"""Contact sheet rows for substitute teachers."""

from typing import Iterable, List, Tuple

from rosterkit.models import Student

def _sort_key(student: Student) -> Tuple[str, str, str]:
    return (
        student.last_name.casefold(),
        student.first_name.casefold(),
        student.student_id
    )

def _check_roster(roster: List[Student]) -> None:
    if not roster:
        raise ValueError("no students to list")
    for student in roster:
        if not student.email:
            name = student.display_name
            raise ValueError(f"no email on file for {name}")

def _row(
    student: Student, name_width: int, section_width: int
) -> str:
    name = student.display_name.ljust(name_width)
    section = student.section.ljust(section_width)
    return f"{name}  {section}  {student.email}"

def _format_rows(roster: List[Student]) -> List[str]:
    name_width = max(len(s.display_name) for s in roster)
    section_width = max(len(s.section) for s in roster)
    return [
        _row(s, name_width, section_width) for s in roster
    ]

# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Name, section and email rows, sorted by name."""
    roster = sorted(students, key=_sort_key)
    _check_roster(roster)
    return _format_rows(roster)
